var n=`0419-sm-rrebr-d`;var r=`world-0419`;var t=`DK`;var o=`northern-europe`;var s=4;var a=29;var d={en:`Smørrebrød`,ua:`Сморреброд`};var g={en:`A traditional dish from Denmark, centered on rye bread, chicken egg, dijon mustard, smoked salmon. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: житній хліб, куряче яйце, діжонська гірчиця, копчений лосось. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`rye-bread`,8,`slice`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`unsalted-butter`,70,`g`],[`dijon-mustard`,14,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`smoked-salmon`,160,`g`],[`cucumber`,130,`g`],[`radish`,100,`g`],[`dill`,18,`g`]]}];var m={slug:n,id:r,country:`DK`,region:o,servings:4,minutes:29,title:d,text:g,steps:l};export{t as country,m as default,r as id,a as minutes,o as region,s as servings,n as slug,l as steps,g as text,d as title};